function weekSelector(){return `<label>WEEK<select onchange="week=+this.value;save();render()">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${week===i+1?'selected':''}>Week ${i+1}</option>`).join('')}</select></label>`}
// Readiness panel visibility is UI-only; it never alters the athlete's readiness data.
const READY_UI_KEY='jr-performance-readiness-ui-v1';
function readyUiState(){try{return JSON.parse(localStorage.getItem(READY_UI_KEY)||'{}')||{}}catch{return {}}}
function readyUiSave(state){try{localStorage.setItem(READY_UI_KEY,JSON.stringify(state))}catch{}}
function readyUiDate(){let n=new Date();return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`}
function readyUiKey(){return `${readyUiDate()}|${week}|${day}`}
function readyUiMode(){let state=readyUiState();return state[readyUiKey()]||'open'}
function setReadyUiMode(mode){let state=readyUiState();let key=readyUiKey();if(mode==='open')delete state[key];else state[key]=mode;for(let k of Object.keys(state))if(!k.startsWith(readyUiDate()+'|'))delete state[k];readyUiSave(state);render()}
// Smart Movement Library v8: session-scoped swaps preserve the programmed plan.
const movementByName=name=>MOVEMENT_CATALOG.find(x=>x.name===name);
function swapMap(w=week,d=day){return session(w,d).swaps||{}}
function activeExercises(d=day,w=week){let swaps=swapMap(w,d);return exercises[d].map((e,i)=>{let replacement=swaps[i];if(!replacement)return e;let meta=movementByName(replacement);return meta?[replacement,meta.category,e[2],e[3],e[4],`Substituted for ${e[0]}. Use coach-approved technique and appropriate loading.`]:e})}
function swappedFrom(i){return swapMap()[i]||null}
function swapExercise(i,name){let base=exercises[day][i],entry=movementByName(name);if(!base||!entry)return;let s=ensureSession(week,day);s.swaps??={};let old=activeExercises()[i][0];if(old===name){closeSwap();return}if(s.items?.[old]?.sets?.some(x=>x.done)&&!confirm('This exercise already has logged sets. Switching will keep those records but show a new exercise. Continue?'))return;if(name===base[0])delete s.swaps[i];else s.swaps[i]=name;save();closeSwap();render();toast(name===base[0]?'Original exercise restored':'Exercise swapped for this workout')}
function resetSwap(i){swapExercise(i,exercises[day][i][0])}
function closeSwap(){document.getElementById('swapOverlay')?.remove()}
function openSwap(i){const original=exercises[day][i],current=activeExercises()[i],base=movementByName(original[0]);if(!base)return;window.swapIndex=i;window.swapQuery='';window.swapEquipment='All';window.swapMode='recommended';drawSwap()}
function drawSwap(){const i=window.swapIndex,original=exercises[day][i],base=movementByName(original[0]);if(!base)return;let old=document.getElementById('swapOverlay');if(old)old.remove();let overlay=document.createElement('div');overlay.id='swapOverlay';overlay.className='video-overlay swap-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Swap exercise');overlay.innerHTML=`<div class="video-sheet swap-sheet"><div class="swap-header"><div><span class="v7-kicker">WORKOUT / EXERCISE SWAP</span><h2>Replace ${esc(original[0])}</h2><p class="mini">Only changes Week ${week} · ${esc(day)}. Your original plan stays intact.</p></div><button class="secondary small" onclick="closeSwap()">✕ Close</button></div><div class="swap-controls"><button class="${window.swapMode==='recommended'?'':'secondary'}" onclick="window.swapMode='recommended';drawSwap()">Recommended</button><button class="${window.swapMode==='all'?'':'secondary'}" onclick="window.swapMode='all';drawSwap()">All movements</button></div><label class="v71-search-label">SEARCH<input type="search" placeholder="Search movements" value="${esc(window.swapQuery||'')}" oninput="window.swapQuery=this.value;updateSwapResults()"></label><label class="v71-search-label">EQUIPMENT<select onchange="window.swapEquipment=this.value;updateSwapResults()">${['All',...new Set(MOVEMENT_CATALOG.map(x=>x.equipment))].map(e=>`<option ${window.swapEquipment===e?'selected':''}>${esc(e)}</option>`).join('')}</select></label><div id="swapResults"></div><div class="notice">Match the movement goal and technique, not just the muscle group. If JR reports pain, do not use exercise swaps to train through it; consult his coach or clinician.</div></div>`;overlay.onclick=e=>{if(e.target===overlay)closeSwap()};document.body.appendChild(overlay);updateSwapResults()}
function updateSwapResults(){let i=window.swapIndex,original=exercises[day][i],base=movementByName(original[0]),query=(window.swapQuery||'').toLowerCase(),eq=window.swapEquipment||'All',recommended=window.swapMode!=='all';let choices=MOVEMENT_CATALOG.filter(x=>(!recommended||(x.pattern===base.pattern&&x.objective===base.objective))&&(eq==='All'||x.equipment===eq)&&(!query||`${x.name} ${x.category} ${x.equipment}`.toLowerCase().includes(query)));choices.sort((a,b)=>Number(b.name===original[0])-Number(a.name===original[0])||a.name.localeCompare(b.name));let targetEl=$('swapResults');if(!targetEl)return;targetEl.innerHTML=`<div class="v71-result-count">${choices.length} ${recommended?'MATCHED':'AVAILABLE'} EXERCISES</div>${choices.map(x=>`<button class="swap-choice" onclick="swapExercise(${i},decodeURIComponent('${encodeURIComponent(x.name)}'))"><span><b>${esc(x.name)}</b><small>${esc(x.equipment)} · ${esc(x.category)} ${JR_RENDERED_VIDEOS[x.name]?'· VIDEO':'· GUIDE PENDING'}</small></span><span>${x.name===original[0]?'ORIGINAL':'SWAP →'}</span></button>`).join('')||'<p class="mini">No matching exercises. Try All movements or another equipment filter.</p>'}`}
function favoriteMovement(name){db.favorites??=[];let idx=db.favorites.indexOf(name);if(idx>=0)db.favorites.splice(idx,1);else db.favorites.push(name);save();updateLibraryResults()}
function renderTrain(){
 const s=ensureSession(week,day);if(!s.date){s.date=localWorkoutDate();save()}
 prefillWorkoutWeights();
 const r=readiness(week,day),state=readinessState(week,day),[done,total]=sessionCompletion(week,day),mode=readyUiMode();
 const readyFields=mode==='open'?`<div class="readiness-body"><div class="grid">${[['energy','Energy (1 low–5 high)',[1,2,3,4,5]],['sleep','Sleep quality (1–5)',[1,2,3,4,5]],['soreness','Muscle soreness (0–5)',[0,1,2,3,4,5]]].map(([key,label,values])=>`<label>${label}<select onchange="setReady('${key}',this.value)"><option value="">Choose</option>${values.map(v=>`<option value="${v}" ${String(r[key])===String(v)?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<label>Any pain (especially arm)?<select onchange="setReady('pain',this.value)"><option value="">Choose</option><option value="no" ${r.pain==='no'?'selected':''}>No</option><option value="yes" ${r.pain==='yes'?'selected':''}>Yes</option></select></label></div><div class="notice ${state.level==='red'?'danger':state.level==='green'?'good':''}">${esc(state.message)}</div><button type="button" class="secondary small readiness-dismiss" onclick="setReadyUiMode('dismissed')">Dismiss for today</button></div>`:`<div class="readiness-compact"><p class="mini">${mode==='dismissed'?'Hidden for today.':'Collapsed.'} ${state.level==='red'?'Pain was reported. Review before training.':''}</p>${mode==='dismissed'?'':`<button class="secondary small" onclick="setReadyUiMode('dismissed')">Dismiss for today</button>`}</div>`;
 $('app').innerHTML=`<div class="v7-workout-heading"><span class="v7-kicker">TRAINING SESSION</span><h1>${day==='Monday'?'LOWER BODY':day==='Thursday'?'UPPER BODY':'TOTAL BODY'} <em>${day==='Monday'?'& SPEED':day==='Thursday'?'& STABILITY':'& AGILITY'}</em></h1><p>Week ${week} of 12 · ${phase(week)}</p></div><div class="card hero"><div class="row">${weekSelector()}<label>WORKOUT DATE<input type="date" value="${esc(s.date||'')}" onchange="setSession('date',this.value)"></label></div><div class="tabrow">${DAYS.map(d=>`<button class="${day===d?'':'secondary'}" onclick="day='${d}';render()">${d}</button>`).join('')}</div><div class="progresslabel"><small>Sets completed</small><b>${done}/${total}</b></div><div class="bar"><span style="width:${total?done/total*100:0}%"></span></div><div class="actionrow"><button class="secondary" onclick="startRest(90)">90s rest</button><button class="secondary" onclick="startRest(120)">2m rest</button><button class="secondary" onclick="startRest(180)">3m rest</button></div></div><div class="card readiness-card"><div class="row readiness-head"><div><h2>60-second readiness check</h2><span class="mini">${mode==='open'?'How are you feeling before training?':mode==='dismissed'?'Hidden for today':'Tap expand to check in'}</span></div><div class="readiness-head-actions"><span class="pill ${state.level==='green'?'green':state.level==='red'?'':'amber'}">${esc(state.label)}</span><button class="secondary small readiness-toggle" onclick="setReadyUiMode(readyUiMode()==='open'?'collapsed':'open')">${mode==='open'?'⌃ Hide':'⌄ Expand'}</button></div></div>${readyFields}</div>${activeExercises().map((e,i)=>exerciseHTML(e,i)).join('')}<div class="card"><h2>Finish workout</h2><div class="grid"><label>Technique<select onchange="setSession('technique',this.value)"><option value="">Choose</option><option value="good" ${s.technique==='good'?'selected':''}>Controlled / good</option><option value="needs-work" ${s.technique==='needs-work'?'selected':''}>Needs improvement</option></select></label><label>Session effort (1–10)<select onchange="setSession('effort',this.value)"><option value="">Choose</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${String(s.effort)===String(i+1)?'selected':''}>${i+1}</option>`).join('')}</select></label></div><label>Notes<textarea placeholder="How did it feel?" oninput="setSession('note',this.value)">${esc(s.note||'')}</textarea></label><button class="wide" onclick="finishWorkout()">${s.finished?'✓ Completed — tap to undo':'✓ Finish workout'}</button><p class="mini">Modified sessions count. Technique, recovery, and health matter more than increasing weight.</p></div>`;
}
function exerciseHTML(e,i){let [n,reps]=target(week,e),s=session(week,day).items?.[e[0]]||{},last=latest(week,day,e[0]),sg=suggestion(week,day,e[0]);let advice=weightAdvice(e[0]);let prev=last?last.sets.map(x=>`${x.weight||'—'} lb × ${x.reps}`).slice(0,3).join(' / '):'No previous entry';return `<section class="card workout-card"><div class="exercise-head"><div><span class="pill gray">${esc(e[1])}</span><h3>${esc(e[0])}</h3><small>${n} sets × ${reps} ${esc(e[4])}</small></div><div class="swap-exercise-actions"><button class="small secondary v7-video-button" onclick="openDemo(${i})">${uiIcon('play')} <span>DEMO</span></button><button class="small secondary" onclick="openSwap(${i})">${uiIcon('swap')} <span>SWAP</span></button></div></div>${swappedFrom(i)?`<div class="swap-original">↳ Original: ${esc(exercises[day][i][0])} <button onclick="resetSwap(${i})">Restore</button></div>`:''}<p class="mini">${esc(e[5])}</p><div class="v7-previous"><span>LAST SESSION</span><b>${esc(prev)}</b></div><div class="smart-weight-hint"><span>WEIGHT SUGGESTION</span><b>${advice.value!=null?esc(advice.value)+' lb':'—'}</b><small>${esc(advice.note)}</small></div>${sg?`<div class="notice ${sg.tone==='danger'?'danger':sg.tone==='green'?'good':''}"><b>${esc(sg.title)}</b><br>${esc(sg.detail)}</div>`:''}<div class="set-head"><span>SET</span><span>WEIGHT (LB)</span><span>REPS / RESULT</span><span>DONE</span></div>${Array.from({length:n},(_,j)=>{let v=s.sets?.[j]||{};return `<div class="set-row ${v.done?'done':''}"><span>${j+1}</span><input type="number" min="0" step="any" inputmode="decimal" aria-label="${esc(e[0])} set ${j+1} weight" placeholder="—" value="${esc(v.weight??'')}" oninput="setValue(${i},${j},'weight',this.value)"><input type="number" min="0" step="any" inputmode="decimal" aria-label="${esc(e[0])} set ${j+1} reps" placeholder="${reps}" value="${esc(v.reps??'')}" oninput="setValue(${i},${j},'reps',this.value)"><button class="set-check-button ${v.done?'checked':''}" aria-pressed="${v.done?'true':'false'}" title="${v.done?'Undo completed set':'Complete set'}" aria-label="Mark set ${j+1} ${v.done?'incomplete':'complete'}" onclick="toggleSet(${i},${j})"><svg class="set-check-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M5 12.5l4.4 4.4L19 7.3"/></svg></button></div>`}).join('')}<div class="stepper"><button class="small secondary" onclick="adjustLoad(${i},-5)">−5 lb</button><button class="small secondary" onclick="adjustLoad(${i},5)">+5 lb</button><button class="small secondary" onclick="copyPrevious(${i})">↻ Last</button></div></section>`}
function setSession(k,v){ensureSession(week,day)[k]=v;save()}
function setReady(k,v){db.readiness[`${week}-${day}`]??={};db.readiness[`${week}-${day}`][k]=v;save();render()}
function ensureSet(i,j){let e=activeExercises()[i][0],s=ensureSession(week,day);s.items??={};s.items[e]??={sets:[]};return s.items[e].sets[j]??={}}
function setValue(i,j,k,v){ensureSet(i,j)[k]=v===''?'':Number(v);save()}
function toggleSet(i,j){let e=activeExercises()[i],v=ensureSet(i,j),was=!!v.done,oldBest=best(e[0],{w:week,d:day,j});if(v.reps==null||v.reps==='')v.reps=target(week,e)[1];v.done=!was;save();if(!was&&Number(v.weight)>oldBest&&Number(v.weight)>0&&Number(v.reps)>0)toast(`🏆 NEW PR! ${e[0]} — ${v.weight} lb`);else if(!was)toast('✓ Set saved — keep it up!');if(!was&&db.settings.autoRest)startRest(Number(db.settings.rest)||90);render()}
function adjustLoad(i,delta){let e=activeExercises()[i],n=target(week,e)[0],s=ensureSession(week,day);let sets=s.items?.[e[0]]?.sets||[],prev=latest(week,day,e[0]);let load=sets.find(x=>x.weight!==''&&x.weight!=null)?.weight??prev?.sets.find(x=>x.weight!==''&&x.weight!=null)?.weight??0;load=Math.max(0,Number(load)+delta);for(let j=0;j<n;j++){let v=ensureSet(i,j);if(!v.done)v.weight=load}save();render()}
function copyPrevious(i){let e=activeExercises()[i],prev=latest(week,day,e[0]);if(!prev){toast('No earlier set data yet');return}let n=target(week,e)[0];for(let j=0;j<n;j++){let v=ensureSet(i,j),a=prev.sets[j]||prev.sets[prev.sets.length-1];if(!v.done&&a){v.weight=a.weight??'';v.reps=a.reps??''}}save();render();toast('Previous values copied')}
function finishWorkout(){let s=ensureSession(week,day);if(!s.finished&&readinessState(week,day).level==='red'&&!confirm('Pain was reported. Do not train through pain. Mark this as a modified/recovery session?'))return;s.finished=!s.finished;save();render();toast(s.finished?'🏅 Workout logged! Consistency wins.':'Workout reopened')}
function openDemo(i){showExerciseVideo(activeExercises()[i][0])}
function startRest(sec){clearInterval(restInterval);restRemaining=sec;renderTimer();restInterval=setInterval(()=>{restRemaining--;renderTimer();if(restRemaining<=0){clearInterval(restInterval);toast('⏱ Rest complete');if(navigator.vibrate)navigator.vibrate([150,90,150])}},1000)}
function stopRest(){clearInterval(restInterval);restRemaining=0;renderTimer()}
function renderTimer(){let el=$('timerDock');if(restRemaining<=0){el.classList.add('hidden');return}el.classList.remove('hidden');el.innerHTML=`<div class="row"><div><small>REST TIMER</small><br><strong>${Math.floor(restRemaining/60)}:${String(restRemaining%60).padStart(2,'0')}</strong></div><div class="actionrow"><button class="small secondary" onclick="restRemaining+=30;renderTimer()">+30s</button><button class="small" onclick="stopRest()">Done</button></div></div>`}
function calendarGrid(dateStr){let dt=new Date(dateStr+'T12:00:00'),year=dt.getFullYear(),month=dt.getMonth(),first=new Date(year,month,1).getDay(),last=new Date(year,month+1,0).getDate();let html='<div class="row"><button class="small secondary" onclick="moveMonth(-1)">‹</button><b>'+dt.toLocaleDateString(undefined,{month:'long',year:'numeric'})+'</b><button class="small secondary" onclick="moveMonth(1)">›</button></div><div class="calendar-grid">';html+=['S','M','T','W','T','F','S'].map(d=>'<small>'+d+'</small>').join('');for(let i=0;i<first;i++)html+='<span></span>';for(let n=1;n<=last;n++){let date=year+'-'+String(month+1).padStart(2,'0')+'-'+String(n).padStart(2,'0'),weekday=WEEKDAYS[new Date(date+'T12:00:00').getDay()],has=db.schedule.some(e=>e.day===weekday)||db.extraEvents.some(e=>e.date===date),selected=date===dateStr;html+='<button class="cal-day '+(selected?'chosen':'')+'" onclick="selectedDate=\''+date+'\';render()">'+n+(has?'<i>•</i>':'')+'</button>'}return html+'</div>'}
function moveMonth(n){let dt=new Date(selectedDate+'T12:00:00');dt.setDate(1);dt.setMonth(dt.getMonth()+n);selectedDate=dt.toISOString().slice(0,10);render()}
function renderSchedule(){let schedule=db.schedule;let d=selectedDate;let weekday=WEEKDAYS[new Date(d+'T12:00:00').getDay()];let extra=db.extraEvents.filter(x=>x.date===d);$('app').innerHTML=`<div class="card hero"><span class="pill">BASEBALL + TRAINING</span><h1>YOUR <span class="accent">SCHEDULE</span></h1><p>Everything in one place. Record pitching and hitting workload to inform recovery.</p><label>Choose a date<input type="date" value="${esc(d)}" onchange="selectedDate=this.value;render()"></label></div><div class="card">${calendarGrid(d)}</div><div class="card"><h2>${esc(weekday)} · ${esc(d)}</h2>${scheduleDay(weekday).map(eventHTML).join('')||'<p>No repeating activities.</p>'}${extra.map(x=>`<div class="event"><div class="event-body"><b>${esc(x.name)}</b><small>${esc(x.time)}</small></div><button class="small secondary" onclick="removeEvent('${esc(x.id)}')">Remove</button></div>`).join('')}<hr class="divider"><h3>Add a one-time activity</h3><div class="grid"><label>Activity<input id="newEventName" placeholder="Tournament / game"></label><label>Time<input id="newEventTime" placeholder="9:00 AM"></label></div><button style="margin-top:12px" onclick="addEvent()">+ Add to ${esc(d)}</button></div><div class="card"><h2>Weekly lineup</h2>${WEEKDAYS.slice(1).concat('Sunday').map(x=>`<div class="daybox"><b>${x}</b>${scheduleDay(x).map(eventHTML).join('')||'<p class="mini">No activity</p>'}</div>`).join('')}</div><div class="card"><h2>Baseball workload log</h2><p class="mini">Use this after lessons or practice. The app flags reported pain but does not diagnose injuries.</p><label>Log date<input type="date" id="baseballDate" value="${esc(d)}" onchange="selectedDate=this.value;render()"></label><div class="grid" style="margin-top:10px"><label>Activity<select id="bbActivity"><option>Pitching</option><option>Practice</option><option>Hitting</option><option>Game</option></select></label><label>Pitch count (if known)<input type="number" min="0" id="bbPitches" placeholder="Optional"></label><label>Throwing effort (1–5)<select id="bbEffort"><option value="">Not recorded</option>${[1,2,3,4,5].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Arm discomfort?<select id="bbPain"><option>No</option><option>Yes</option></select></label></div><label style="display:block;margin-top:10px">Notes<textarea id="bbNotes" placeholder="Lesson notes, throwing workload, arm feel..."></textarea></label><button onclick="addBaseballLog()">Save baseball log</button><div style="margin-top:12px">${Object.entries(db.baseball).filter(([date])=>date===d).flatMap(([date,arr])=>arr.map((x,i)=>`<div class="event"><div class="event-body"><b>${esc(x.activity)}</b><small>${esc(date)} · ${x.pitches||'—'} pitches · arm discomfort: ${esc(x.pain)}</small><small>${esc(x.notes||'')}</small></div><button class="small secondary" onclick="removeBaseballLog('${esc(date)}',${i})">✕</button></div>`)).join('')||'<small>No logs for this date.</small>'}</div></div><div class="card"><h2>Edit repeating schedule</h2><p class="mini">Changes are saved locally. The workout program remains Monday, Thursday, and Saturday.</p>${schedule.map(e=>`<div class="event"><div class="event-body"><b>${esc(e.day)} — ${esc(e.name)}</b><small>${esc(e.time)}</small></div><button class="small secondary" onclick="editEvent('${esc(e.id)}')">Edit</button></div>`).join('')}<button class="secondary" onclick="addRecurring()">+ Add repeating activity</button></div>`}
function addEvent(){let name=$('newEventName').value.trim(),time=$('newEventTime').value.trim();if(!name)return toast('Enter an activity name');db.extraEvents.push({id:String(Date.now()),date:selectedDate,name,time});save();render()}
function removeEvent(id){db.extraEvents=db.extraEvents.filter(e=>e.id!==id);save();render()}
function editEvent(id){let e=db.schedule.find(x=>x.id===id);if(!e)return;let name=prompt('Activity',e.name);if(name===null||!name.trim())return;let time=prompt('Time',e.time);if(time===null)return;e.name=name.trim();e.time=time.trim();save();render()}
function addRecurring(){let name=prompt('Repeating activity name');if(!name?.trim())return;let dayName=prompt('Day of week (e.g., Tuesday)','Tuesday');if(!WEEKDAYS.includes(dayName))return toast('Enter a valid weekday');let time=prompt('Time','Flexible');db.schedule.push({id:'custom-'+Date.now(),day:dayName,name:name.trim(),time:time||'Flexible',type:'baseball'});save();render()}
function addBaseballLog(){let d=$('baseballDate').value,entry={activity:$('bbActivity').value,pitches:$('bbPitches').value,effort:$('bbEffort').value,pain:$('bbPain').value,notes:$('bbNotes').value};db.baseball[d]??=[];db.baseball[d].push(entry);save();render();toast('Baseball workload saved')}
function removeBaseballLog(d,i){db.baseball[d].splice(i,1);save();render()}
const BADGES=[['🏁','First Workout','Complete 1 workout',()=>completedCount()>=1],['🔥','Full Week','Complete all 3 workouts in any week',()=>Array.from({length:12},(_,i)=>DAYS.every(d=>finished(i+1,d))).some(Boolean)],['🏅','12-Week Finisher','Complete all 36 workouts',()=>completedCount()===36],['💪','Strength PR','Log a weighted personal best',()=>['Barbell back squat','Barbell front squat','Barbell strict press'].some(n=>best(n)>0)],['⚡','Speed Progress','Improve 10-yard sprint time',()=>testImproved('10-yard sprint')],['🚀','Explosive Progress','Improve a jump measurement',()=>testImproved('Vertical jump')||testImproved('Broad jump')],['🧠','Smart Training','Complete a readiness check',()=>Object.values(db.readiness).some(r=>r.energy&&r.sleep&&r.soreness!==''&&r.soreness!=null)],['🛡️','Recovery Matters','Complete a recovery-week workout',()=>[4,8,12].some(w=>DAYS.some(d=>finished(w,d)))] ];
function testImproved(name){let t=db.tests[name]||{},a=Number(t[1]),b=Number(t[12]||t[6]);if(!a||!b)return false;return ['10-yard sprint','20-yard sprint','5-10-5 shuttle'].includes(name)?b<a:b>a}
function renderProgress(){let done=completedCount();$('app').innerHTML=`<div class="card hero"><span class="pill">YOUR DEVELOPMENT</span><h1>PROGRESS <span class="accent">REPORT</span></h1><p>Celebrate consistency, strength, speed, and movement quality—not just lifting more.</p><div class="grid"><div><small>WORKOUTS</small><div class="metric">${done}/36</div></div><div><small>BADGES EARNED</small><div class="metric">${BADGES.filter(b=>b[3]()).length}/${BADGES.length}</div></div></div></div><div class="card"><h2>Strength trends</h2><label>Exercise<select id="chartLift" onchange="drawChart()">${['Barbell back squat','Barbell front squat','Barbell strict press','Trap bar deadlift','Dumbbell bench press'].map(x=>`<option>${x}</option>`).join('')}</select></label><canvas class="chart" id="liftChart" width="700" height="270" aria-label="Strength progress chart"></canvas><p class="mini">Highest logged weight for completed sets in each week.</p></div><div class="card"><h2>Athletic performance scorecard</h2><p class="mini">Enter baseline, Week 6, and Week 12 results. Lower sprint times and higher jumps indicate improvement.</p><div class="scroll"><table><tr><th>TEST</th><th>W1</th><th>W6</th><th>W12</th><th>CHANGE</th></tr>${tests.map(t=>`<tr><td>${esc(t[0])}<br><small>${esc(t[1])}</small></td>${[1,6,12].map(w=>`<td><input type="number" min="0" step="any" inputmode="decimal" aria-label="${esc(t[0])} week ${w}" value="${esc(db.tests[t[0]]?.[w]??'')}" oninput="setTest('${esc(t[0])}',${w},this.value)"></td>`).join('')}<td id="test-${tests.indexOf(t)}">${testDelta(t)}</td></tr>`).join('')}</table></div></div><div class="card"><h2>Achievements</h2><div class="badge-grid">${BADGES.map(([emoji,title,description,fn])=>`<div class="badge ${fn()?'':'locked'}"><div class="emoji">${emoji}</div><b>${esc(title)}</b><small>${esc(description)}</small>${fn()?'<span class="pill green">UNLOCKED</span>':'<span class="pill gray">LOCKED</span>'}</div>`).join('')}</div></div><div class="card"><h2>Weekly consistency</h2>${Array.from({length:12},(_,i)=>{let n=DAYS.filter(d=>finished(i+1,d)).length;return `<div class="progresslabel"><small>Week ${i+1}</small><b>${n}/3</b></div><div class="bar"><span style="width:${n/3*100}%"></span></div>`}).join('')}</div>`;drawChart()}
function setTest(name,w,v){db.tests[name]??={};db.tests[name][w]=v===''?'':Number(v);save();let t=tests.find(x=>x[0]===name),cell=$('test-'+tests.indexOf(t));if(cell)cell.textContent=testDelta(t)}
function testDelta(t){let obj=db.tests[t[0]]||{},a=Number(obj[1]),b=Number(obj[12]||obj[6]);if(!a||!b)return '—';let delta=b-a;if(t[2]==='lower')return `${delta<0?'↑':delta>0?'↓':'='} ${Math.abs(delta).toFixed(2)} ${t[1]}`;return `${delta>0?'↑':delta<0?'↓':'='} ${Math.abs(delta).toFixed(1)} ${t[1]}`}
function drawChart(){let c=$('liftChart');if(!c)return;let ctx=c.getContext('2d'),name=$('chartLift').value,vals=[];for(let w=1;w<=12;w++){let sets=DAYS.flatMap(d=>session(w,d).items?.[name]?.sets||[]);let a=sets.filter(x=>x.done&&Number(x.weight)>0).map(x=>Number(x.weight));vals.push(a.length?Math.max(...a):null)}ctx.clearRect(0,0,700,270);ctx.fillStyle='#b7bcc8';ctx.font='15px system-ui';ctx.fillText('Highest logged load (lb)',40,25);ctx.strokeStyle='#505663';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(45,42);ctx.lineTo(45,225);ctx.lineTo(678,225);ctx.stroke();let max=Math.max(10,...vals.filter(v=>v!=null))*1.2;let started=false;ctx.strokeStyle='#cbd0d5';ctx.lineWidth=4;ctx.beginPath();vals.forEach((v,i)=>{let x=58+i*54,y=225-(v/max)*165;ctx.fillStyle='#bec2cd';ctx.fillText(i+1,x-4,247);if(v==null){started=false;return}if(!started){ctx.moveTo(x,y);started=true}else ctx.lineTo(x,y)});ctx.stroke();vals.forEach((v,i)=>{if(v==null)return;let x=58+i*54,y=225-(v/max)*165;ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fillStyle='#e0e4e8';ctx.fill();ctx.fillStyle='#fff';ctx.font='13px system-ui';ctx.fillText(String(v),x-9,y-12)});if(!vals.some(v=>v!=null)){ctx.fillStyle='#aeb2bc';ctx.fillText('Log completed strength sets to see progress.',80,145)}}
function profileData(){return db.profile||{name:'JR',team:'',position:'',bats:'',throws:'',number:'',goal:'Build strength, speed and explosiveness',goalWorkouts:3,trainingNotes:''}}
function updateProfile(field,value){let p=db.profile??={...profileData()};p[field]=field==='goalWorkouts'?Math.max(1,Math.min(7,Number(value)||3)):String(value).slice(0,250);save();toast('Profile saved')}
function confirmProfileSave(){save();view='athlete';render();toast('✓ Profile saved successfully')}
function profileEdit(){let p=profileData();$('app').innerHTML=`<div class="card"><button class="secondary small" onclick="view='athlete';render()">← Profile</button><h1>EDIT <span class="accent">ATHLETE</span></h1><p>Changes save automatically when you finish editing a field. Tap Save Profile to return.</p><div class="photo-edit"><div class="profile-avatar">${p.photo?`<img src="${esc(p.photo)}" alt="Current athlete photo">`:esc((p.name||'JR').slice(0,2).toUpperCase())}</div><div><label>Upload profile photo<input type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" onchange="uploadAthletePhoto(event)"></label><button class="secondary small" style="margin-top:9px" onclick="removeAthletePhoto()">Remove photo</button><p class="mini">Photo is resized on this device and saved with JR’s local profile. Avoid photos showing other children.</p></div></div><div class="grid"><label>Display name<input maxlength="40" value="${esc(p.name)}" onchange="updateProfile('name',this.value)"></label><label>Primary position<input maxlength="40" placeholder="e.g. Pitcher" value="${esc(p.position)}" onchange="updateProfile('position',this.value)"></label><label>Jersey number<input maxlength="5" placeholder="Optional" value="${esc(p.number)}" onchange="updateProfile('number',this.value)"></label><label>Bats<select onchange="updateProfile('bats',this.value)">${['','Right','Left','Switch'].map(v=>`<option value="${v}" ${p.bats===v?'selected':''}>${v||'Not set'}</option>`).join('')}</select></label><label>Throws<select onchange="updateProfile('throws',this.value)">${['','Right','Left'].map(v=>`<option value="${v}" ${p.throws===v?'selected':''}>${v||'Not set'}</option>`).join('')}</select></label></div><label style="display:block;margin-top:13px">Training goal<textarea maxlength="250" onchange="updateProfile('goal',this.value)">${esc(p.goal)}</textarea></label><label style="display:block;margin-top:13px">Weekly workout goal<select onchange="updateProfile('goalWorkouts',this.value)">${[1,2,3,4,5,6,7].map(v=>`<option value="${v}" ${Number(p.goalWorkouts)===v?'selected':''}>${v} workout${v===1?'':'s'}</option>`).join('')}</select></label><label style="display:block;margin-top:13px">Training notes<textarea maxlength="250" placeholder="Equipment preferences, reminders…" onchange="updateProfile('trainingNotes',this.value)">${esc(p.trainingNotes||'')}</textarea></label><div class="actionrow" style="margin-top:16px"><button class="wide" onclick="confirmProfileSave()">✓ Save Profile</button></div><div class="notice" style="margin-top:14px">Avoid storing medical information or personal contact details in this profile.</div></div>`}
function removeAthletePhoto(){let p=db.profile??={...profileData()};delete p.photo;save();render();toast('Profile picture removed')}
async function uploadAthletePhoto(ev){const file=ev.target.files?.[0];if(!file)return;if(file.size>15*1024*1024){alert('Choose a photo smaller than 15 MB.');return}try{let bitmap=await createImageBitmap(file),size=256,canvas=document.createElement('canvas');canvas.width=canvas.height=size;let ctx=canvas.getContext('2d');let side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,size,size);bitmap.close?.();let photo=canvas.toDataURL('image/jpeg',.75);if(photo.length>180000)throw Error('Image too large after resizing');let p=db.profile??={...profileData()};p.photo=photo;save();render();toast('Photo updated')}catch(e){alert('Could not process that photo. Try a JPG or PNG. '+e.message)}}
function measurements(){return Array.isArray(db.measurements)?db.measurements:[]}
function latestMeasure(field){return [...measurements()].filter(x=>Number(x[field])>0).sort((a,b)=>a.date.localeCompare(b.date)).at(-1)}
function measurementChart(field,unit){let points=[...measurements()].filter(x=>Number(x[field])>0).sort((a,b)=>a.date.localeCompare(b.date));if(!points.length)return '<p class="mini">No measurements yet. Add an entry to start a chart.</p>';if(points.length===1)return `<div class="metric">${esc(points[0][field])} <small>${unit}</small></div><p class="mini">Add another dated measurement to see a trend.</p>`;let vals=points.map(x=>Number(x[field])),min=Math.min(...vals),max=Math.max(...vals),range=Math.max(max-min,1),xy=vals.map((v,i)=>[(20+i*280/(vals.length-1)).toFixed(1),(140-(v-min)/range*112).toFixed(1)]),line=xy.map(a=>a.join(',')).join(' ');return `<svg class="growth-chart" viewBox="0 0 320 170" role="img" aria-label="${field} trend from ${vals[0]} to ${vals.at(-1)} ${unit}"><line x1="20" y1="140" x2="300" y2="140" stroke="#626a73"/><polyline points="${line}" fill="none" stroke="#e2e6ea" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${xy.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4" fill="#f4f5f6"/>`).join('')}<text x="20" y="161" fill="#c8cdd2" font-size="11">${esc(points[0].date)}</text><text x="300" y="161" text-anchor="end" fill="#c8cdd2" font-size="11">${esc(points.at(-1).date)}</text></svg><p class="mini">${vals[0]} → ${vals.at(-1)} ${unit} · ${points.length} measurements</p>`}
function renderGrowth(){let w=latestMeasure('weight'),h=latestMeasure('height'),height=h?Number(h.height):0,feet=Math.floor(height/12),inch=(height%12).toFixed(1).replace(/\.0$/,'');let rows=[...measurements()].sort((a,b)=>b.date.localeCompare(a.date));$('app').innerHTML=`<div class="card hero"><button class="secondary small" onclick="view='athlete';render()">← Profile</button><span class="pill">ATHLETE DEVELOPMENT</span><h1>HEIGHT & WEIGHT</h1><p>Track JR’s growth over time without weight targets or comparisons to other athletes.</p></div><div class="grid"><div class="card"><small>LATEST WEIGHT</small><div class="metric">${w?esc(w.weight)+' <small>lb</small>':'—'}</div><p class="mini">${w?esc(w.date):'Not recorded'}</p></div><div class="card"><small>LATEST HEIGHT</small><div class="metric">${h?`${feet}′ ${inch}″`:'—'}</div><p class="mini">${h?esc(h.date):'Not recorded'}</p></div></div><div class="card" style="margin-top:13px"><h2>Add measurement</h2><form onsubmit="addMeasurement(event)"><div class="grid"><label>Date<input id="measureDate" type="date" required value="${new Date().toLocaleDateString('en-CA')}"></label><label>Weight (lb)<input id="measureWeight" type="number" inputmode="decimal" min="20" max="600" step="0.1" placeholder="Optional"></label><label>Height — feet<input id="measureFeet" type="number" inputmode="numeric" min="2" max="8" step="1" placeholder="Optional"></label><label>Height — inches<input id="measureInches" type="number" inputmode="decimal" min="0" max="11.9" step="0.1" placeholder="Optional"></label></div><button class="wide" type="submit" style="margin-top:14px">+ Save measurement</button></form><p class="mini">Enter weight, height, or both. Measure under similar conditions for useful trends.</p></div><div class="card"><h2>Weight history</h2>${measurementChart('weight','lb')}</div><div class="card"><h2>Height history</h2>${measurementChart('height','in')}</div><div class="card"><h2>Measurement history</h2>${rows.length?rows.map(x=>`<div class="event"><div class="event-body"><b>${esc(x.date)}</b><small>${x.weight?esc(x.weight)+' lb':''}${x.weight&&x.height?' · ':''}${x.height?`${Math.floor(x.height/12)}′ ${(x.height%12).toFixed(1).replace(/\.0$/,'')}″`:''}</small></div><button class="secondary small" aria-label="Delete measurement on ${esc(x.date)}" onclick="deleteMeasurement('${esc(x.id)}')">Delete</button></div>`).join(''):'<p class="mini">No measurements recorded yet.</p>'}</div><div class="notice">Height and weight change naturally during adolescence. These charts are for observing growth, not judging performance or setting weight-loss goals. Profile and measurement data stay on this device unless cloud sync is enabled.</div>`}
function addMeasurement(ev){ev.preventDefault();let date=$('measureDate').value,weight=$('measureWeight').value,ft=$('measureFeet').value,inch=$('measureInches').value;if(!date||(!weight&&ft===''&&inch==='')){alert('Enter a date and at least one measurement.');return}if((ft!==''||inch!=='')&&ft===''){alert('Enter feet when recording height.');return}let w=weight!==''?Number(weight):null,h=ft!==''?Number(ft)*12+Number(inch||0):null;if((w!==null&&(!Number.isFinite(w)||w<20||w>600))||(h!==null&&(!Number.isFinite(h)||h<24||h>107.9))){alert('Check the measurements and try again.');return}db.measurements??=[];db.measurements.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,7),date,weight:w,height:h});save();render();toast('Measurement saved')}
function deleteMeasurement(id){if(!confirm('Delete this measurement?'))return;db.measurements=measurements().filter(x=>x.id!==id);save();render();toast('Measurement deleted')}
function profileSettings(){let p=profileData();$('app').innerHTML=`<div class="card"><button class="secondary small" onclick="view='athlete';render()">← Profile</button><h1>WORKOUT <span class="accent">SETTINGS</span></h1><label>Default rest timer<select onchange="db.settings.rest=+this.value;save()">${[60,90,120,180].map(v=>`<option value="${v}" ${Number(db.settings.rest)===v?'selected':''}>${v} seconds</option>`).join('')}</select></label><label style="display:flex;gap:10px;align-items:center;margin-top:15px"><input type="checkbox" ${db.settings.autoRest?'checked':''} onchange="db.settings.autoRest=this.checked;save()"> Auto-start rest timer after a set</label><label style="display:block;margin-top:15px">Weekly workout target<select onchange="updateProfile('goalWorkouts',this.value)">${[1,2,3,4,5,6,7].map(v=>`<option ${Number(p.goalWorkouts)===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="notice" style="margin-top:16px">Workout progression is a suggestion, not a requirement. A coach should supervise technique and adjust for pitching workload and recovery.</div></div>`}
function profileMenu(title,desc,iconName,action){return `<button class="profile-menu" onclick="${action}"><span class="profile-menu-icon">${iconName}</span><span class="profile-menu-text"><b>${title}</b><small>${desc}</small></span><span class="profile-chevron">›</span></button>`}
function renderProfile(){if(view==='parent')return renderParent();if(view==='library')return renderLibrary();if(view==='data')return renderData();if(view==='edit')return profileEdit();if(view==='settings')return profileSettings();if(view==='growth')return renderGrowth();let p=profileData(),count=completedCount(),total=36,pct=Math.min(100,Math.round(count/total*100)),current=DAYS.filter(d=>finished(week,d)).length,goal=Math.max(1,Number(p.goalWorkouts)||3),prNames=['Barbell back squat','Barbell front squat','Barbell strict press','Trap bar deadlift'],prs=prNames.filter(n=>best(n)>0),logged=Object.values(db.baseball).flat().length,first=Object.values(db.sessions).filter(x=>x.finished&&x.date).map(x=>x.date).sort()[0];$('app').innerHTML=`<div class="card profile-hero"><div class="profile-head"><div class="profile-avatar" aria-label="JR athlete avatar">${p.photo?`<img src="${esc(p.photo)}" alt="Athlete profile picture">`:esc((p.name||'JR').trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><div class="profile-identity"><span class="pill">ATHLETE PROFILE</span><h1>${esc(p.name||'JR')}${p.number?` <span class="profile-number">#${esc(p.number)}</span>`:''}</h1><p>BASEBALL PERFORMANCE ATHLETE</p><div class="profile-tags">${p.position?`<span>${esc(p.position)}</span>`:''}${p.bats?`<span>Bats ${esc(p.bats)}</span>`:''}${p.throws?`<span>Throws ${esc(p.throws)}</span>`:''}</div></div></div><button class="secondary small" onclick="view='edit';render()">✎ Edit athlete profile</button></div><div class="profile-stats"><div class="card profile-stat"><b>${count}</b><small>Workouts</small></div><div class="card profile-stat"><b>${prs.length}</b><small>Lifts tracked</small></div><div class="card profile-stat"><b>${logged}</b><small>Baseball logs</small></div></div><div class="card"><div class="row"><h2>Training journey</h2><span class="pill gray">WEEK ${week} / 12</span></div><div class="progresslabel"><span>12-week program</span><b>${count}/${total} sessions</b></div><div class="bar"><span style="width:${pct}%"></span></div><div class="profile-week"><div><strong>${current} / ${goal}</strong><small>Workouts completed this week</small></div><div><strong>${phase(week)}</strong><small>Current phase</small></div></div><div class="profile-goal"><span>🎯</span><div><b>My training goal</b><p>${esc(p.goal||'Build strength, speed and explosiveness')}</p></div></div><div class="actionrow"><button class="secondary" onclick="nav('progress')">View progress →</button><button class="secondary" onclick="nav('train')">Go to training →</button></div></div><div class="card"><h2>Athlete development</h2><div class="growth-summary"><div><small>WEIGHT</small><b>${latestMeasure('weight')?esc(latestMeasure('weight').weight)+' lb':'—'}</b></div><div><small>HEIGHT</small><b>${latestMeasure('height')?`${Math.floor(latestMeasure('height').height/12)}′ ${(latestMeasure('height').height%12).toFixed(1).replace(/\.0$/,'')}″`:'—'}</b></div></div><button class="wide" onclick="view='growth';render()">+ Add Height or Weight</button><button class="secondary wide" style="margin-top:8px" onclick="view='growth';render()">View measurement history & charts →</button></div><div class="card"><h2>My training</h2>${profileMenu('Height & weight','Measurements, history and growth charts','📏',"view='growth';render()")}${profileMenu('Personal records','Strength history and athletic test results','🏆',"nav('progress')")}${profileMenu('Exercise library','Videos, technique cues and demonstrations','🎥',"view='library';render()")}${profileMenu('Training calendar','Lessons, practices and gym sessions','📅',"nav('schedule')")}</div><div class="card"><h2>Account & preferences</h2>${profileMenu('Edit athlete details','Photo, position, jersey and goals','👤',"view='edit';render()")}${profileMenu('Workout settings','Rest timer and training preferences','⚙️',"view='settings';render()")}${profileMenu('Parent dashboard','Local overview of progress and recovery','👨‍👦',"view='parent';render()")}${profileMenu('Data, backups & cloud','Export, restore and optional parent-managed sync','☁️',"view='data';render()")}</div><div class="profile-footer"><span>⚾ BASEBALL PERFORMANCE</span><span>JR PERFORMANCE • v8.0</span></div><div class="notice">Athlete profiles are stored locally unless a parent configures cloud backup. Stop activity when pain is reported and consult a qualified clinician for persistent or throwing-related pain.</div>`}

// Exercise video center: safe, coach-curated links can be saved locally. Unverified videos are never presented as vetted.
