 o+=`<circle cx="${p.shoulder[0]}" cy="${p.shoulder[1]}" r="10" fill="${press?hot:metal}" stroke="#d7dfe6" stroke-width="1.4"/>`;
 o+=`<path d="M${pt(neck)} L${pt(head)}" stroke="#adb8c3" stroke-width="11" stroke-linecap="round"/>`;
